import { planDependentClaimInsertion } from "./caret-aware-claim-plan";

// Independent decoder for the supported expressions generated by this test. Do not
// use the production parser as the oracle: compare stable original claim identities.
function referenceNumbers(text: string): number[] {
  const reference = /权\s*利\s*要\s*求(.*?)所述/su.exec(text)?.[1];
  if (!reference) return [];
  const numbers: number[] = [];
  for (const part of reference.replace(/任一项/gu, "").split(/[,，、]\s*(?:或者|或)?|或者|或/u)) {
    const bounds = part
      .trim()
      .split(/[-－—–~～至到]/u)
      .map(Number);
    const start = bounds[0];
    const end = bounds[1] ?? start;
    if (
      start === undefined ||
      end === undefined ||
      !Number.isInteger(start) ||
      !Number.isInteger(end)
    )
      throw new Error(`Invalid test reference: ${part}`);
    for (let n = start; n <= end; n++) numbers.push(n);
  }
  return [...new Set(numbers)].sort((a, b) => a - b);
}

test("3000 seeded insertions preserve original target identities and all characteristic text", () => {
  let seed = 84721;
  const pick = (length: number) => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed % length;
  };
  for (let run = 0; run < 100; run++) {
    const paragraphs = [
      "1. 一种装置，其特征在于：原文甲。",
      ...Array.from(
        { length: 8 },
        (_, i) =>
          `${i + 2}. 根据权利${i % 2 ? "\n" : ""}要求${i + 1}所述的一种装置，其特征在于：原文${i + 2}。`,
      ),
      "10. 根据权利要求1至3、5，或7任一项所述的一种装置，其特征在于：原文末。",
    ];
    const ids = paragraphs.map((_, i) => `old-${i}`);
    const targets = new Map(
      ids.map((id, i) => [
        id,
        referenceNumbers(paragraphs[i] ?? "")
          .map((n) => ids[n - 1])
          .sort(),
      ]),
    );
    for (let step = 0; step < 30; step++) {
      const index = pick(paragraphs.length);
      const parent = ids[index];
      const result = planDependentClaimInsertion({
        paragraphs,
        cursorParagraphIndex: index,
        cursorParagraphIsEmpty: false,
      });
      if (!result.ok) throw new Error(`run ${run}, step ${step}: ${result.error.message}`);
      const plan = result.value;
      const originalBodies = paragraphs.map((text) => text.split("其特征在于：")[1]);
      for (const change of [
        ...plan.paragraphNumberReplacements,
        ...plan.referenceReplacements,
      ].sort((a, b) => b.paragraphIndex - a.paragraphIndex || b.from - a.from)) {
        const text = paragraphs[change.paragraphIndex];
        if (text === undefined) throw new Error("Invalid replacement paragraph");
        paragraphs[change.paragraphIndex] =
          text.slice(0, change.from) + change.text + text.slice(change.to);
      }
      expect(paragraphs.map((text) => text.split("其特征在于：")[1])).toEqual(originalBodies);
      const id = `new-${run}-${step}`;
      paragraphs.splice(plan.insertionIndex, 0, plan.replacementText);
      ids.splice(plan.insertionIndex, 0, id);
      targets.set(id, [parent]);
      for (const [i, text] of paragraphs.entries()) {
        expect(text.startsWith(`${i + 1}.`)).toBe(true);
        expect(
          referenceNumbers(text)
            .map((n) => ids[n - 1])
            .sort(),
        ).toEqual(targets.get(ids[i] ?? ""));
      }
    }
  }
});
